{
  "category_edits": [
    {
      "category": "embedding_representation",
      "rationale": "Apply the supplied power-0.9 normalization to the shared history and candidate embedding table across all four datasets. This retains modest learned magnitude variation and zero padding while preserving dimensions, GRU topology, scoring, loss and optimizer. The generated predictor imports the updated model and validates matching metadata.",
      "edits": [
        {
          "find": "        embeddings = torch.nn.functional.normalize(embeddings, p=2, dim=-1, eps=1e-12)",
          "replace": "        norms = embeddings.norm(p=2, dim=-1, keepdim=True).clamp(min=1e-12)\n        embeddings = embeddings / norms.pow(0.9)"
        },
        {
          "find": "            \"sequence_readout\": \"gru_0.8_causal_mean_0.2_half_life_3\",",
          "replace": "            \"sequence_readout\": \"gru_0.8_causal_mean_0.2_half_life_3\",\n            \"item_embedding_normalization\": \"l2_power_0.9\","
        },
        {
          "find": "        if meta.get(\"sequence_readout\") != \"gru_0.8_causal_mean_0.2_half_life_3\":\n            raise RuntimeError(f\"Incompatible GRU sequence readout for {ds}\")",
          "replace": "        if meta.get(\"sequence_readout\") != \"gru_0.8_causal_mean_0.2_half_life_3\":\n            raise RuntimeError(f\"Incompatible GRU sequence readout for {ds}\")\n        if meta.get(\"item_embedding_normalization\") != \"l2_power_0.9\":\n            raise RuntimeError(f\"Incompatible item embedding normalization for {ds}\")"
        }
      ]
    }
  ],
  "change_summary": "Replace strict unit normalization with e/max(||e||₂,1e-12)^0.9 in the tied item embedding and synchronize checkpoint metadata with the embedded predictor."
}
